import{_ as t,o as h,c as a,a3 as i}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/bat-dau/giao-dien-chung.png",m=JSON.parse('{"title":"Giao diện chung","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/giao-dien-chung.md","filePath":"bat-dau/giao-dien-chung.md","lastUpdated":1782138127000}'),g={name:"bat-dau/giao-dien-chung.md"};function r(s,n,c,e,u,d){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="giao-dien-chung" tabindex="-1">Giao diện chung <a class="header-anchor" href="#giao-dien-chung" aria-label="Permalink to &quot;Giao diện chung&quot;">​</a></h1><p>Sau khi đăng nhập, mọi trang trong FADO AssetFlow đều dùng chung một bố cục: <strong>thanh điều hướng</strong> (sidebar) bên trái và <strong>thanh trên cùng</strong> (topbar). Hiểu bố cục này giúp bạn di chuyển nhanh giữa các chức năng.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Bố cục:</strong> Sidebar (trái) + Topbar (trên) + vùng nội dung chính.</li><li><strong>Sidebar:</strong> 4 nhóm menu — Tổng Quan · Công Việc · Nhân Sự · Hệ Thống.</li><li><strong>Topbar:</strong> tìm kiếm · chuông thông báo · quét QR · menu người dùng.</li><li><strong>Menu hiển thị theo quyền:</strong> mỗi người chỉ thấy các mục mình được phép truy cập.</li></ul></div><h2 id="thanh-đieu-huong-sidebar" tabindex="-1">Thanh điều hướng (Sidebar) <a class="header-anchor" href="#thanh-đieu-huong-sidebar" aria-label="Permalink to &quot;Thanh điều hướng (Sidebar)&quot;">​</a></h2><p><img src="'+o+'" alt="Giao diện chung — sidebar và topbar"></p><p>Sidebar được cố định bên trái, gồm từ trên xuống:</p><ol><li><strong>Logo</strong> — nhấn để quay về Dashboard.</li><li><strong>Các nhóm menu</strong> chia làm 4 phần:</li></ol><table tabindex="0"><thead><tr><th>Nhóm</th><th>Các mục</th></tr></thead><tbody><tr><td><strong>TỔNG QUAN</strong></td><td>Dashboard · Tra Cứu · Lịch Sử</td></tr><tr><td><strong>CÔNG VIỆC</strong></td><td>Ticket Hỗ Trợ · Công Việc · Đặt Phòng Họp · Duyệt Yêu Cầu</td></tr><tr><td><strong>NHÂN SỰ</strong></td><td>Dữ Liệu Chấm Công · Hợp đồng &amp; Hồ sơ · Yêu Cầu Tuyển Dụng · Quản Lý Hồ Sơ · Nguồn Nhân Lực</td></tr><tr><td><strong>HỆ THỐNG</strong></td><td>Quản lý Tài sản · Tổ Chức · Biểu Mẫu · Người Dùng · Cài Đặt</td></tr></tbody></table><ol start="3"><li><strong>Khu vực người dùng</strong> ở dưới cùng — hiển thị avatar, tên, vai trò và nút <strong>Đăng Xuất</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Menu hiện theo quyền</p><p>Mỗi mục menu chỉ hiện nếu vai trò/quyền của bạn cho phép. Ví dụ Dashboard, Quản lý Tài sản, Tổ Chức, Lịch Sử… mặc định dành cho Super Admin/Admin. Các mục <strong>Dữ Liệu Chấm Công</strong>, <strong>Tra Cứu</strong>, <strong>Ticket Hỗ Trợ</strong>, <strong>Đặt Phòng Họp</strong> và <strong>Hợp đồng &amp; Hồ sơ</strong> luôn hiện cho mọi người dùng. Xem chi tiết tại <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p></div><h3 id="badge-so-tren-menu" tabindex="-1">Badge số trên menu <a class="header-anchor" href="#badge-so-tren-menu" aria-label="Permalink to &quot;Badge số trên menu&quot;">​</a></h3><p>Một số mục menu có <strong>huy hiệu số</strong> (badge) hình vòng cung xoay, cho biết số việc cần xử lý:</p><ul><li><strong>Duyệt Yêu Cầu</strong> — số yêu cầu chờ duyệt (màu vàng).</li><li><strong>Ticket Hỗ Trợ</strong> — số ticket cần chú ý (màu đỏ).</li><li><strong>Công Việc</strong> — số công việc liên quan (màu chàm).</li><li><strong>Đặt Phòng Họp</strong> — lịch đặt phòng (màu xanh ngọc).</li><li><strong>Người Dùng</strong>, <strong>Yêu Cầu Tuyển Dụng</strong>, <strong>Hợp đồng &amp; Hồ sơ</strong>, <strong>Quản Lý Hồ Sơ</strong>, <strong>Nguồn Nhân Lực</strong> — số mục chờ xử lý tương ứng.</li></ul><p>Badge tự cập nhật định kỳ (khoảng mỗi 60 giây) và theo thời gian thực khi có thay đổi.</p><h3 id="thu-gon-sidebar" tabindex="-1">Thu gọn sidebar <a class="header-anchor" href="#thu-gon-sidebar" aria-label="Permalink to &quot;Thu gọn sidebar&quot;">​</a></h3><ul><li>Trên <strong>màn hình lớn</strong>: nhấn nút mũi tên (<code>‹</code> / <code>›</code>) cạnh logo để <strong>thu gọn/mở rộng</strong> sidebar. Khi thu gọn chỉ hiện biểu tượng; di chuột vào để xem tên mục.</li><li>Lựa chọn thu gọn được ghi nhớ cho lần sau.</li></ul><h2 id="thanh-tren-cung-topbar" tabindex="-1">Thanh trên cùng (Topbar) <a class="header-anchor" href="#thanh-tren-cung-topbar" aria-label="Permalink to &quot;Thanh trên cùng (Topbar)&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Topbar: ô tìm kiếm bên trái, các biểu tượng chức năng và menu người dùng bên phải. <em>(Ảnh sẽ được bổ sung.)</em></p></div><p>Từ trái sang phải, topbar gồm:</p><ul><li><strong>Ô tìm kiếm</strong> — tìm tài sản theo tên hoặc mã (<code>AF-...</code>). Trên màn hình lớn hỗ trợ phím tắt <code>⌘K</code>.</li><li><strong>Chuông thông báo</strong> — hiển thị thông báo hệ thống (ví dụ cảnh báo tên miền sắp hết hạn). Số trên chuông là số thông báo chưa đọc.</li><li><strong>Biểu tượng QR</strong> — mở trình <strong>quét mã QR</strong> để tra cứu nhanh tài sản.</li><li><strong>Menu người dùng</strong> — nhấn avatar/tên để mở menu: <ul><li><strong>Hồ Sơ Cá Nhân</strong> — xem sơ yếu lý lịch của chính bạn.</li><li><strong>Đăng Xuất</strong>.</li></ul></li></ul><h2 id="vung-noi-dung-chinh" tabindex="-1">Vùng nội dung chính <a class="header-anchor" href="#vung-noi-dung-chinh" aria-label="Permalink to &quot;Vùng nội dung chính&quot;">​</a></h2><p>Vùng còn lại hiển thị nội dung của trang đang mở. Bố cục được căn giữa, tự co giãn theo kích thước màn hình.</p><h2 id="responsive-—-dung-tren-đien-thoai" tabindex="-1">Responsive — dùng trên điện thoại <a class="header-anchor" href="#responsive-—-dung-tren-đien-thoai" aria-label="Permalink to &quot;Responsive — dùng trên điện thoại&quot;">​</a></h2><p>Trên <strong>điện thoại/màn hình nhỏ</strong>, giao diện chuyển sang chế độ app: sidebar được thay bằng <strong>thanh tab dưới đáy</strong> (Trang chủ · Chấm công · Duyệt/Công việc · Menu · Tài khoản), mọi chức năng khác nằm trong tab <strong>Menu</strong>. Bố cục các trang tự chuyển sang <strong>1 cột</strong> để dễ thao tác.</p><div class="tip custom-block"><p class="custom-block-title">📱 Cài như một ứng dụng</p><p>Bạn có thể <strong>cài FADO AssetFlow lên màn hình chính</strong> điện thoại (Android &amp; iPhone) để mở nhanh, chạy toàn màn hình như app thật. Xem hướng dẫn chi tiết tại <strong><a href="/help/bat-dau/dien-thoai.html">Dùng trên điện thoại &amp; cài app</a></strong>.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi không thấy một mục menu mà đồng nghiệp có?</strong> Menu hiển thị theo quyền của từng tài khoản. Nếu cần truy cập, đề nghị Admin cấp quyền cho module đó.</p><p><strong>Badge số nghĩa là gì?</strong> Là số lượng mục đang chờ bạn xử lý ở mục tương ứng. Khi xử lý xong, số sẽ giảm.</p><p><strong>Làm sao quay nhanh về Dashboard?</strong> Nhấn vào <strong>logo</strong> ở sidebar hoặc topbar.</p><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/dang-nhap.html">Đăng nhập</a> · <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a> · <a href="/help/chuc-nang/dashboard.html">Dashboard</a></p>',31)])])}const p=t(g,[["render",r]]);export{m as __pageData,p as default};
